// Controller baseline only. No S/T/U implementation or real user scope access.
mod picker;
use serde_json::{Value,json};
fn main(){let args:Vec<String>=std::env::args().collect();match args[1].as_str(){
 "picker"=>picker::probe(&args[2]),
 "review"=>{let cases:Value=serde_json::from_str(include_str!("../../../contracts/redacted-report-v1/cases.json")).unwrap();let mut snapshots=Vec::new();for (index,c) in cases["golden_cases"].as_array().unwrap().iter().enumerate(){let mut r=water_contracts::v1::parse_report(&c["input"].to_string()).unwrap();let source=if c["id"].as_str().unwrap().starts_with("retained-j-"){"retained_j_capture"}else{r.scan_id=water_contracts::v1::OpaqueId::new(&format!("review-h-{index}")).unwrap();"synthetic_memory"};let view=water_report_view::v1::project_report(&r).unwrap();let summary=water_summary_export::v1::summarize_report(&r).unwrap();let redacted=water_redacted_report::v1::redact_report(&r).unwrap();let raw=water_redacted_report::v1::to_json(&redacted).unwrap();assert_eq!(serde_json::from_str::<Value>(&raw).unwrap(),c["expected"]);snapshots.push(json!({"source_kind":source,"view":view,"summary":summary,"redacted_json":raw}));}println!("{}",json!({"bundle_version":"water.scan-review-bundle.v1","snapshots":snapshots}));},
 "manifest"=>{let c:Value=serde_json::from_str(include_str!("../../../contracts/node-manifest-v1/cases.json")).unwrap();for p in c["valid"].as_array().unwrap(){let v:Value=serde_json::from_str(p["raw"].as_str().unwrap()).unwrap();assert!(v.is_object());assert_eq!(p["expected"]["project_membership_verified"],false);}for p in c["errors"].as_array().unwrap(){if p["error"]=="InvalidJson"{assert!(serde_json::from_str::<Value>(p["raw"].as_str().unwrap()).is_err());}}println!("{}",json!({"serde_json_existing_dependency":true,"valid_cases":c["valid"].as_array().unwrap().len(),"raw_error_cases":c["errors"].as_array().unwrap().len(),"U_product_tested":false}));},
 _=>panic!("unsupported controller probe")}}
